]);

// ============================================================================
// SECTION 5: The Bell Tower Pavilion (Shoro) & Bonsho Bell (x: 18 to 28, z: -9 to 1)
// ============================================================================
section("Bell Tower Pavilion", [
  // Stone Kidan base (10x10, y: 0 to 6)
  box({
    at: [18, 0, -9],
