  place({ part: "3633", at: [21, 7, -1], colour: "timber", turn: 0 }),
  place({ part: "3633", at: [26, 7, -6], colour: "timber", turn: 90 }),
  // 4 Corner Pillars (y: 7 to 16)
  ...[[19, -8], [26, -8], [19, -1], [26, -1]].map(([x, z]) => [
    place({ part: "14716", at: [x, 7, z], colour: "verm" })
  ]),
  // Upper Tie-Beam & Bracket Frieze (y: 16 to 19)
  room({ at: [19, 16, -8], size: [8, 3, 8], colour: "verm" }),
  ...bracketRing(19, 27, -8, 0, 16, 2, "verm", "timber"),

  // Central Ceiling Crossbeam & Hanging Bronze Bonsho Bell (x: 22..24, z: -5..-3)
  place({ part: "3795", at: [20, 18, -5], colour: "darkTimber" }),
  place({ part: "3022", at: [22, 17, -5], colour: "gold" }),
