  place({ part: "3941", at: [22, 10, -5], colour: "bronze" }),
  place({ part: "4032b", at: [22, 9, -5], colour: "bronze" }),

  // Suspended Wooden Striker Log (Shumoku) & Bell-Ringer Monk
  place({ part: "3005", at: [20, 7, -5], colour: "timber" }),
