  place({ part: "90398", at: [20, 7, -3], colour: "orange", turn: 270 }),

  // Shoro Hip Roof (y = 19, size 8x8, overhang 1)
  roof({
    style: "hip",
    at: [19, 19, -8],
    size: [8, 8],
    overhang: 1,
