  }),
  ...roofCorners(18, 27, -9, 0, 19),
  place({ part: "3942c", at: [22, 31, -5], colour: "gold" }),
  place({ part: "6908", at: [22, 37, -5], colour: "gold" })
]);

// ============================================================================
// SECTION 6: Sculpted Weeping Sakura Tree, Autumn Momiji Tree & Bamboo Grove
// ============================================================================
section("Sakura, Momiji and Bamboo", [
  // 1) Weeping Sakura (Cherry Blossom) Tree at Front-Left (x: -29 to -21, z: -26 to -18)
  floor({ at: [-28, 0, -25], size: [7, 7], layers: 2, colour: "moss", top: "tile" }),
  place({ part: "3039", at: [-26, 2, -23], colour: "darkTimber", turn: 0 }),
  place({ part: "3003", at: [-26, 5, -22], colour: "darkTimber" }),
  place({ part: "3003", at: [-25, 8, -22], colour: "darkTimber" }),
  place({ part: "3001", at: [-26, 11, -22], colour: "darkTimber" }),
  // Layered Sakura Blossom Canopy (2417 5x6 leaves & 2423 3x4 leaves in white + flowers)
  place({ part: "2417", at: [-28, 14, -24], colour: "sakura", turn: 0 }),
  place({ part: "2417", at: [-25, 15, -23], colour: "sakura", turn: 90 }),
  place({ part: "2423", at: [-27, 16, -22], colour: "sakura", turn: 0 }),
  place({ part: "2423", at: [-25, 17, -21], colour: "sakura", turn: 180 }),
  ...[[-27, 15, -23], [-24, 16, -22], [-26, 17, -21], [-25, 18, -20], [-27, 15, -20]].map(([x, y, z], i) =>
    place({ part: "24866", at: [x, y, z], colour: i % 2 === 0 ? "red" : "white" })
  ),
  // Fallen blossoms on the moss mound
  place({ part: "24866", at: [-27, 2, -24], colour: "white" }),
  place({ part: "24866", at: [-23, 2, -20], colour: "red" }),

  // 2) Crimson Momiji (Autumn Japanese Maple) Tree at Front-Right (x: 20 to 28, z: -25 to -17)
  floor({ at: [20, 0, -24], size: [7, 7], layers: 2, colour: "moss", top: "tile" }),
  place({ part: "3039", at: [22, 2, -22], colour: "darkTimber", turn: 180 }),
  place({ part: "3003", at: [22, 5, -21], colour: "darkTimber" }),
  place({ part: "3001", at: [21, 8, -21], colour: "darkTimber" }),
  place({ part: "3003", at: [22, 11, -20], colour: "darkTimber" }),
  // Layered Autumn Maple Canopy (red, dark red, orange)
  place({ part: "2417", at: [20, 14, -23], colour: "maple", turn: 0 }),
  place({ part: "2417", at: [22, 15, -22], colour: "verm", turn: 90 }),
  place({ part: "2423", at: [21, 16, -21], colour: "mapleOrange", turn: 0 }),
  place({ part: "2423", at: [23, 17, -20], colour: "maple", turn: 180 }),
  ...[[21, 15, -22], [23, 16, -21], [22, 17, -20], [24, 18, -19]].map(([x, y, z], i) =>
    place({ part: "24866", at: [x, y, z], colour: i % 2 === 0 ? "orange" : "yellow" })
  ),

  // 3) Rear Sanctuary Pine & Bamboo Gardens flanking the Zen Garden
  floor({ at: [-20, 0, 8], size: [6, 8], layers: 2, colour: "moss", top: "tile" }),
  place({ part: "3471", at: [-19, 2, 10], colour: "green" }),
  floor({ at: [14, 0, 8], size: [6, 8], layers: 2, colour: "moss", top: "tile" }),
  place({ part: "3471", at: [15, 2, 10], colour: "green" }),
  // Tall Bamboo Stalks (Round Bricks 3062b in lime & green)
  ...[[-15, 9], [-16, 14], [18, 9], [19, 14]].map(([x, z], i) =>
    range(5 + (i % 2)).map(h =>
      place({ part: "3062b", at: [x, 2 + h * 3, z], colour: h % 2 === 0 ? "green" : "lime" })
    )
  )
]);

