{"check_build": {"code": "script({
  title: "Renge-in — Japanese Buddhist Temple of the Golden Lotus",
  description: "Pure Land (Jodo) Buddhist temple sanctuary featuring a two-tiered Irimoya Main Hall (Hondo) with a Great Golden Buddha on a lotus throne, a Three-Storey Pagoda (Sanju-no-to), a Shoro Bell Pavilion with hanging bronze Bonsho bell, a Sacred Lotus & Koi Pond with an arched vermilion Taikobashi bridge, a Chozuya purification pavilion, Jokoro incense burner, sculpted Sakura and Momiji trees, and a rear Karesansui Zen rock garden.",
  palette: {
    stone: { mix: ["light bluish grey", "light bluish grey", "dark bluish grey"] },
    darkStone: "dark bluish grey",
    lightStone: "light bluish grey",
    plaster: "white",
    verm: "dark red",
    crimson: "red",
    timber: "reddish brown",
    darkTimber: "dark brown",
    roof: "dark bluish grey",
    roofAccent: "black",
    gold: "pearl gold",
    bronze: "sand green",
    sand: "tan",
    darkSand: "dark tan",
    water: "trans light blue",
    deepWater: "dark blue",
    moss: "olive green",
    foliage: "dark green",
    sakura: "white",
    maple: "red",
    mapleOrange: "orange"
  }
});

// Reusable carved stone lantern (Toro) component (2x2 footprint, 11 plates tall)
component("Toro", {
  size: [2, 2],
  ops: [
    place({ part: "3022", at: [0, 0, 0], colour: "darkStone" }),
    place({ part: "4032b", at: [0, 1, 0], colour: "lightStone" }),
    place({ part: "3941", at: [0, 2, 0], colour: "lightStone" }),
    place({ part: "3022", at: [0, 5, 0], colour: "darkStone" }),
    place({ part: "3024", at: [0, 6, 0], colour: "trans yellow" }),
    place({ part: "3024", at: [1, 6, 0], colour: "lightStone" }),
    place({ part: "3024", at: [0, 6, 1], colour: "lightStone" }),
    place({ part: "3024", at: [1, 6, 1], colour: "trans yellow" }),
    place({ part: "3022", at: [0, 7, 0], colour: "darkStone" }),
    place({ part: "54200", at: [0, 8, 0], colour: "darkStone", turn: 0 }),
    place({ part: "54200", at: [1, 8, 0], colour: "darkStone", turn: 270 }),
    place({ part: "54200", at: [0, 8, 1], colour: "darkStone", turn: 90 }),
    place({ part: "54200", at: [1, 8, 1], colour: "darkStone", turn: 180 })
  ]
});

// Helper for Tokyo (dougong) inverted-slope bracket rings around a rectangular wall
function bracketRing(minX, maxX, minZ, maxZ, y, step = 2, col1 = "verm", col2 = "timber") {
  const ops = [];
  let idx = 0;
  for (let x = minX + 1; x <= maxX - 2; x += step) {
    const c = (idx++ % 2 === 0) ? col1 : col2;
    ops.push(place({ part: "3665a", at: [x, y, minZ - 1], colour: c, turn: 0 }));
    ops.push(place({ part: "3665a", at: [x, y, maxZ - 1], colour: c, turn: 180 }));
  }
  idx = 0;
  for (let z = minZ + 1; z <= maxZ - 2; z += step) {
    const c = (idx++ % 2 === 0) ? col1 : col2;
    ops.push(place({ part: "3665a", at: [minX - 1, y, z], colour: c, turn: 90 }));
    ops.push(place({ part: "3665a", at: [maxX - 1, y, z], colour: c, turn: 270 }));
  }
  return ops;
}

// Helper for upturned roof corner eave ornaments
function roofCorners(minX, maxX, minZ, maxZ, y) {
  return [
    place({ part: "3023b", at: [minX - 1, y, minZ - 1], colour: "roof", turn: 0 }),
    place({ part: "54200", at: [minX - 1, y + 1, minZ - 1], colour: "gold", turn: 180 }),
    place({ part: "3023b", at: [maxX - 1, y, minZ - 1], colour: "roof", turn: 0 }),
    place({ part: "54200", at: [maxX, y + 1, minZ - 1], colour: "gold", turn: 180 }),
    place({ part: "3023b", at: [minX - 1, y, maxZ], colour: "roof", turn: 0 }),
    place({ part: "54200", at: [minX - 1, y + 1, maxZ], colour: "gold", turn: 0 }),
    place({ part: "3023b", at: [maxX - 1, y, maxZ], colour: "roof", turn: 0 }),
    place({ part: "54200", at: [maxX, y + 1, maxZ], colour: "gold", turn: 0 })
  ];
}

// ============================================================================
// SECTION 1: Sacred Lotus & Koi Pond, Stepped Stone Terraces & Zen Rock Garden
// ============================================================================
section("Pond, Terraces and Zen Garden", [
  // Sacred Lotus & Koi Pond (Hojo-ike) in the foreground (z: -27 to -17)
  floor({ at: [-18, 0, -27], size: [36, 10], layers: 1, colour: "deepWater" }),
  floor({ at: [-18, 1, -27], size: [36, 10], layers: 1, colour: "water", top: "tile" }),

  // Natural stepped stone & moss banks framing the pond
  box({ at: [-19, 0, -28], size: [15, 3, 1], colour: "stone", top: "tile" }),
  box({ at: [4, 0, -28], size: [15, 3, 1], colour: "stone", top: "tile" }),
  box({ at: [-19, 0, -27], size: [1, 3, 10], colour: "stone", top: "tile" }),
  box({ at: [18, 0, -27], size: [1, 3, 10], colour: "stone", top: "tile" }),
  // Mossy rock ledges along pond edge
  place({ part: "3039", at: [-17, 2, -27], colour: "darkStone", turn: 180 }),
  place({ part: "3040b", at: [-15, 2, -27], colour: "moss", turn: 180 }),
  place({ part: "3039", at: [-9, 2, -27], colour: "stone", turn: 180 }),
  place({ part: "3039", at: [7, 2, -27], colour: "stone", turn: 180 }),
  place({ part: "3040b", at: [14, 2, -27], colour: "moss", turn: 180 }),
  place({ part: "3039", at: [15, 2, -27], colour: "darkStone", turn: 180 }),

  // Floating Lotus Lily Pads (4032b + 24866 flowers)
  ...[[-15, -25], [-12, -21], [-8, -24], [-14, -19], [7, -24], [11, -20], [14, -25], [13, -19]].map(([x, z], i) => [
    place({ part: "4032b", at: [x, 2, z], colour: i % 2 === 0 ? "green" : "bright green" }),
    place({ part: "24866", at: [x + (i % 2), 3, z + ((i >> 1) % 2)], colour: i % 3 === 0 ? "white" : (i % 3 === 1 ? "red" : "yellow") })
  ]),

  // Swimming Koi Carp in the pond
  place({ part: "11477", at: [-10, 2, -21], colour: "orange", turn: 270 }),
  place({ part: "54200", at: [-11, 2, -21], colour: "white", turn: 90 }),
  place({ part: "11477", at: [-6, 2, -23], colour: "red", turn: 0 }),
  place({ part: "54200", at: [-6, 2, -21], colour: "white", turn: 180 }),
  place({ part: "11477", at: [5, 2, -22], colour: "white", turn: 90 }),
  place({ part: "54200", at: [7, 2, -22], colour: "red", turn: 270 }),
  place({ part: "11477", at: [9, 2, -25], colour: "orange", turn: 0 }),
  place({ part: "54200", at: [9, 2, -23], colour: "orange", turn: 180 }),

  // Central Pilgrim Courtyard (Sando) (z: -17 to -8, x: -18 to 18)
  floor({ at: [-18, 0, -17], size: [36, 9], layers: 2, colour: "stone", top: "tile" }),
  // Side walkways to Pagoda (-X) and Bell Pavilion (+X)
  floor({ at: [-26, 0, -16], size: [8, 5], layers: 2, colour: "stone", top: "tile" }),
  floor({ at: [18, 0, -8], size: [2, 6], layers: 2, colour: "stone", top: "tile" }),

  // Main Hall Raised Masonry Platform (Kidan) (x: -14 to 14, z: -8 to 10, y: 0 to 6)
  box({
    at: [-14, 0, -8],
    size: [28, 6, 18],
    colour: "stone",
    texture: "masonry",
    quoins: "darkStone",
    top: "tile"
  }),

  // Rear Karesansui (Zen Raked Gravel & Rock Garden) (x: -13 to 13, z: 10 to 20)
  floor({ at: [-13, 0, 10], size: [26, 10], layers: 2, colour: "lightStone" }),
  // Raked gravel rows (2412b grille tiles in tan and lightStone)
  ...range(-12, 12, 2).map(x =>
    range(11, 19, 1).map(z => {
      const inRock1 = (x >= -10 && x <= -6 && z >= 13 && z <= 17);
      const inRock2 = (x >= 6 && x <= 10 && z >= 14 && z <= 18);
      const inStair = (x >= -4 && x <= 2 && z >= 10 && z <= 14);
      if (inRock1 || inRock2 || inStair) return null;
      return place({
        part: "2412b",
        at: [x, 2, z],
        colour: (z % 2 === 0) ? "sand" : "lightStone",
        turn: 0
      });
    })
  ),
  // Zen Rock Island 1 (West Horai-jima)
  place({ part: "3001", at: [-9, 2, 14], colour: "darkStone" }),
  place({ part: "3039", at: [-9, 5, 14], colour: "darkStone", turn: 0 }),
  place({ part: "3040b", at: [-7, 5, 14], colour: "moss", turn: 180 }),
  place({ part: "4460b", at: [-8, 5, 14], colour: "darkStone", turn: 0 }),
  place({ part: "54200", at: [-10, 2, 15], colour: "moss", turn: 90 }),
  // Zen Rock Island 2 (East Kame-jima)
  place({ part: "3003", at: [7, 2, 15], colour: "darkStone" }),
  place({ part: "3039", at: [7, 5, 15], colour: "stone", turn: 90 }),
  place({ part: "3040b", at: [9, 2, 15], colour: "moss", turn: 270 }),
  place({ part: "54200", at: [6, 2, 16], colour: "darkStone", turn: 90 }),
  // Low tiled Zen garden border curb at z = 19..20
  wall({ from: [-13, 19], to: [12, 19], y: 2, height: 3, colour: "plaster", top: "tile" }),
  wall({ from: [-13, 10], to: [-13, 19], y: 2, height: 3, colour: "plaster", top: "tile" }),
  wall({ from: [12, 10], to: [12, 19], y: 2, height: 3, colour: "plaster", top: "tile" })
]);

// ============================================================================
// SECTION 2: Vermilion Taikobashi Bridge, Jokoro Incense Burner, Chozuya & Toro
// ============================================================================
section("Bridge, Courtyard Shrine and Lanterns", [
  // Arched Vermilion Drum Bridge (Taikobashi) spanning z: -27 to -17, x: -4 to 4
  // Bridge abutments & stepped arch deck
  box({ at: [-4, 0, -27], size: [8, 3, 2], colour: "stone", interior: "solid" }),
  box({ at: [-4, 0, -19], size: [8, 3, 2], colour: "stone", interior: "solid" }),
  box({ at: [-4, 2, -25], size: [8, 3, 2], colour: "verm", interior: "solid" }),
  box({ at: [-4, 2, -21], size: [8, 3, 2], colour: "verm", interior: "solid" }),
  // Central bridge crown (z: -23 to -21, y: 4 to 6, leaving water passage under at y: 0..4)
  floor({ at: [-4, 4, -23], size: [8, 2], layers: 2, colour: "verm" }),
  // Timber walking deck tiles & step treads
  ...[-27, -26].map(z => [
    place({ part: "2431", at: [-3, 3, z], colour: "timber" }),
    place({ part: "3069b", at: [1, 3, z], colour: "timber" })
  ]),
  ...[-19, -18].map(z => [
    place({ part: "2431", at: [-3, 3, z], colour: "timber" }),
    place({ part: "3069b", at: [1, 3, z], colour: "timber" })
  ]),
  ...[-25, -24, -21, -20].map(z => [
    place({ part: "2431", at: [-3, 5, z], colour: "timber" }),
    place({ part: "3069b", at: [1, 5, z], colour: "timber" })
  ]),
  ...[-23, -22].map(z => [
    place({ part: "2431", at: [-3, 6, z], colour: "timber" }),
    place({ part: "3069b", at: [1, 6, z], colour: "timber" })
  ]),
  // Vermilion side railings & golden Giboshi posts along x = -4 and x = 3
  ...[-4, 3].map(x => [
    // End posts (z = -27 and z = -18)
    place({ part: "3005", at: [x, 3, -27], colour: "verm" }),
    place({ part: "6908", at: [x, 6, -27], colour: "gold" }),
    place({ part: "3005", at: [x, 3, -18], colour: "verm" }),
    place({ part: "6908", at: [x, 6, -18], colour: "gold" }),
    // Railing slopes
    place({ part: "11477", at: [x, 3, -26], colour: "verm", turn: 0 }),
    place({ part: "11477", at: [x, 5, -24], colour: "verm", turn: 0 }),
    place({ part: "11477", at: [x, 5, -21], colour: "verm", turn: 180 }),
    place({ part: "11477", at: [x, 3, -19], colour: "verm", turn: 180 }),
    // Crown posts (z = -23 and z = -22)
    place({ part: "3004", at: [x, 6, -23], colour: "verm", turn: 90 }),
    place({ part: "98138", at: [x, 9, -23], colour: "gold" }),
    place({ part: "98138", at: [x, 9, -22], colour: "gold" })
  ]),

  // Great Bronze Incense Cauldron (Jokoro) in the courtyard (x: -2 to 2, z: -15 to -11)
  floor({ at: [-2, 2, -15], size: [4, 4], layers: 1, colour: "darkStone", top: "tile" }),
  place({ part: "3022", at: [-1, 3, -14], colour: "gold" }),
  place({ part: "3941", at: [-1, 4, -14], colour: "bronze" }),
  place({ part: "4032b", at: [-1, 7, -14], colour: "gold" }),
  place({ part: "4589", at: [-1, 8, -14], colour: "white" }),
  place({ part: "4589", at: [0, 8, -13], colour: "lightStone" }),
  // Pilgrim & Monk at the Jokoro
  place({ part: "90398", at: [-3, 2, -14], colour: "orange", turn: 270 }),
  place({ part: "90398", at: [2, 2, -13], colour: "dark blue", turn: 90 }),

  // Chozuya (Water Purification Pavilion) at right courtyard (x: 9 to 15, z: -16 to -12)
  floor({ at: [9, 2, -16], size: [6, 4], layers: 1, colour: "darkStone", top: "tile" }),
  // Stone water basin (Tsukubai)
  box({ at: [11, 3, -15], size: [2, 2, 2], colour: "stone", interior: "solid" }),
  place({ part: "3069b", at: [11, 5, -15], colour: "water" }),
  place({ part: "3062b", at: [11, 5, -14], colour: "bronze" }),
  place({ part: "4599b", at: [11, 8, -14], colour: "gold", turn: 0 }),
  // 4 Timber Corner Pillars (height 9 plates: y = 3 to 12)
  place({ part: "14716", at: [9, 3, -16], colour: "timber" }),
  place({ part: "14716", at: [14, 3, -16], colour: "timber" }),
  place({ part: "14716", at: [9, 3, -13], colour: "timber" }),
  place({ part: "14716", at: [14, 3, -13], colour: "timber" }),
  // Chozuya Gable Roof (y = 12)
  roof({ style: "gable", at: [9, 12, -16], size: [6, 4], overhang: 1, colour: "roof", gable: "plaster" }),

  // 6 Carved Stone Lanterns (Toro)
  instance({ component: "Toro", at: [-7, 0, -28] }),
  instance({ component: "Toro", at: [5, 0, -28] }),
  instance({ component: "Toro", at: [-7, 2, -11] }),
  instance({ component: "Toro", at: [5, 2, -11] }),
  instance({ component: "Toro", at: [-21, 2, -15] }),
  instance({ component: "Toro", at: [-11, 2, 16] })
]);

// ============================================================================
// SECTION 3: The Main Hall (Hondo / Kondo) & Great Golden Buddha (Daibutsu)
// ============================================================================
section("Main Hall and Golden Buddha", [
  // Front Stone Staircase (Kizahashi) (x: -4 to 4, z: -12 to -8, climbing +z from y=2 to y=6)
  stairs({ at: [-4, 2, -12], width: 8, steps: 4, dir: "+z", rise: 1, run: 1, colour: "stone", top: "tile" }),
